/bin/zsh -lc "node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { discountedTotal, splitCents } from './money.mjs';
import { overlaps, mergeWindows } from './windows.mjs';
for (const [cents, percent, expected] of [[1000, 20, 800], [123, 0, 123], [123, 100, 0], [1, 50, 1], [3, 50, 2], [0, 75, 0]]) {
  assert.equal(discountedTotal(cents, percent), expected);
}
for (let total = 0; total <= 200; total++) {
  for (let people = 1; people <= 30; people++) {
    const shares = splitCents(total, people);
    assert.equal(shares.length, people);
    assert.equal(shares.reduce((a, b) => a + b, 0), total);
    shares.forEach((share, i) => {
      assert.ok(Number.isInteger(share));
      assert.equal(share, Math.floor(total / people) + Number(i < total % people));
    });
  }
}
let overlapChecks = 0;
for (let startA = -3; startA < 4; startA++) {
  for (let endA = startA + 1; endA <= 5; endA++) {
    for (let startB = -3; startB < 4; startB++) {
      for (let endB = startB + 1; endB <= 5; endB++) {
        assert.equal(overlaps({ start: startA, end: endA }, { start: startB, end: endB }), Math.max(startA, startB) < Math.min(endA, endB));
        overlapChecks++;
      }
    }
  }
}
const cases = [[], [{start: 2, end: 3}], [{start: 5, end: 7}, {start: 1, end: 3}, {start: 3, end: 6}], [{start: 1, end: 9}, {start: 2, end: 3}, {start: 12, end: 14}], [{start: 0, end: 1}, {start: 3, end: 4}]];
const expected = [[], [{start: 2, end: 3}], [{start: 1, end: 7}], [{start: 1, end: 9}, {start: 12, end: 14}], [{start: 0, end: 1}, {start: 3, end: 4}]];
cases.forEach((input, i) => {
  const snapshot = structuredClone(input);
  input.forEach(Object.freeze);
  Object.freeze(input);
  const result = mergeWindows(input);
  assert.deepEqual(result, expected[i]);
  assert.deepEqual(input, snapshot);
  assert.notEqual(result, input);
  result.forEach(window => assert.ok("'!input.includes(window)));
  if (result.length) result[0].end += 100;
  assert.deepEqual(input, snapshot);
});
console.log(`Passed: discount boundaries and half cents; 6,030 splits; ${overlapChecks} overlap cases; merge ordering, touching, nesting, gaps, empty input, immutability and independent objects.`);
JS'

